-- NexEstate CSV import — שלב 2
-- יעד: nexuservice@gmail.com

DO $$
DECLARE
  v_user_id uuid;
BEGIN
  SELECT id INTO v_user_id FROM auth.users WHERE lower(email) = lower('nexuservice@gmail.com');
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'משתמש לא נמצא: nexuservice@gmail.com. התחבר/הירשם פעם אחת ואז הרץ שוב.';
  END IF;

  INSERT INTO public.profiles (id, email, full_name, role)
  VALUES (v_user_id, lower('nexuservice@gmail.com'), COALESCE(
    (SELECT raw_user_meta_data->>'full_name' FROM auth.users WHERE id = v_user_id),
    split_part('nexuservice@gmail.com', '@', 1), 'משתמש'), 'broker')
  ON CONFLICT (id) DO UPDATE SET role = EXCLUDED.role, email = EXCLUDED.email;

  INSERT INTO public.properties (id, title, address, city, kind, status, visibility, price, rooms, bathrooms, area_sqm, floor, total_floors, parking_spots, year_built, lat, lng, description, featured, broker_id, owner_id, created_by, images, documents, features)
  VALUES ('a0000001-0000-0000-0000-000000000001'::uuid, 'בניין שקטל ', 'המתכת 34', 'כרמיאל', 'commercial', 'for_rent', 'private', 0, 0, NULL, 5861, NULL, NULL, 0, NULL, NULL, NULL, 'מרכז עסקים מרכזי עם משרדים, תעשייה ומחסנים', false, v_user_id, v_user_id, v_user_id, '{}', '{}', '{}')
